/*
 * A006841  Permutation arrays of period n.
 * https://oeis.org/A006841
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, nice
 * Formula:   Burnside count over the group of order 8n^2 generated by the
 *            dihedral group D_n acting on positions, D_n acting on values,
 *            and inversion of the permutation: a(n) = ( Sum_{cycle types t}
 *            c_t^2 * z_t + 2n * Sum_{g in D_n} r(g) ) / (8n^2), where c_t =
 *            number of elements of D_n with cycle type t, z_t...
 * Range:     u8 n <= 8, u16 n <= 11, u32 n <= 15, u64 n <= 23, u128 n <= 23,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

typedef struct { seq_t q; uint64_t r; } qr_t;

static qr_t qr_small(uint64_t v, uint64_t D)
{
    qr_t x;
    x.q = (seq_t)(idx_t)(v / D);
    x.r = v % D;
    return x;
}

static qr_t qr_mul(qr_t x, uint64_t f, uint64_t D)
{
    unsigned __int128 t = (unsigned __int128)x.r * f;
    qr_t y;
    y.q = x.q * (seq_t)(idx_t)f + (seq_t)(idx_t)(uint64_t)(t / D);
    y.r = (uint64_t)(t % D);
    return y;
}

static qr_t qr_add(qr_t x, qr_t y, uint64_t D)
{
    uint64_t s = x.r + y.r;
    qr_t z;
    z.q = x.q + y.q;
    if (s >= D) { z.q += 1; s -= D; }
    z.r = s;
    return z;
}

static uint64_t euler_phi(uint64_t m)
{
    uint64_t res = m, p;
    for (p = 2; p * p <= m; p++) {
        if (m % p == 0) {
            while (m % p == 0) m /= p;
            res -= res / p;
        }
    }
    if (m > 1) res -= res / m;
    return res;
}

/* number of square roots of a permutation consisting of m cycles of length k */
static qr_t sqrt_count(uint64_t k, uint64_t m, uint64_t D)
{
    qr_t f0 = qr_small(1, D), f1 = qr_small((k & 1) ? 1 : 0, D), f2;
    uint64_t i;
    if (m == 0) return f0;
    for (i = 2; i <= m; i++) {
        f2 = qr_mul(f0, (i - 1) * k, D);
        if (k & 1) f2 = qr_add(f2, f1, D);
        f0 = f1;
        f1 = f2;
    }
    return f1;
}

/* k^m * m! */
static qr_t centralizer(uint64_t k, uint64_t m, uint64_t D)
{
    qr_t z = qr_small(1, D);
    uint64_t i;
    for (i = 1; i <= m; i++) {
        z = qr_mul(z, k, D);
        z = qr_mul(z, i, D);
    }
    return z;
}

seq_t a(idx_t n)
{
    uint64_t D, d, c, b;
    qr_t p1, p2, t;
    if (n <= 2) return (seq_t)1;
    D = 8 * (uint64_t)n * (uint64_t)n;
    p1 = qr_small(0, D);
    p2 = qr_small(0, D);

    /* rotations: phi(d) elements of type d^(n/d) */
    for (d = 1; d <= n; d++) {
        if (n % d) continue;
        c = euler_phi(d);
        p2 = qr_add(p2, qr_mul(sqrt_count(d, n / d, D), c, D), D);
        if (d == 2) c += n / 2; /* reflections of type 2^(n/2) share this cycle type */
        t = qr_mul(centralizer(d, n / d, D), c * c, D);
        p1 = qr_add(p1, t, D);
    }

    if (n & 1) {
        /* n reflections of type 1^1 2^b */
        b = (n - 1) / 2;
        t = qr_mul(centralizer(2, b, D), n * n, D);
        p1 = qr_add(p1, t, D);
        p2 = qr_add(p2, qr_mul(sqrt_count(2, b, D), n, D), D);
    } else {
        /* n/2 reflections of type 1^2 2^b, n/2 of type 2^(n/2) */
        b = (n - 2) / 2;
        c = n / 2;
        t = qr_mul(centralizer(2, b, D), 2 * c * c, D);
        p1 = qr_add(p1, t, D);
        p2 = qr_add(p2, qr_mul(sqrt_count(2, b, D), 2 * c, D), D);
        p2 = qr_add(p2, qr_mul(sqrt_count(2, n / 2, D), c, D), D);
    }

    p2 = qr_mul(p2, 2 * (uint64_t)n, D);
    t = qr_add(p1, p2, D);
    return t.q;
}
